INSERT INTO `scc_base_quicksearch_config` (`QUICKSEARCH_CONFIG_ID`, `NAME`, `QUERY_DATASOURCE`, `QUERY_MODULE`, `QUERY_LANGUAGE_TYPE`, `QUERY_MATCH_OPERATOR`, `QUERY_TABLE`, `QUERY_MAX_SIZE`, `QUERY_MODE`, `CODE_ATTR`, `VALUE_ATTR`, `QUERY_LANGUAGE`, `QUERY_LANGUAGE_CUSTOM`, `DIALOG_ENABLED`, `DIALOG_QUERY_TYPE`, `DIALOG_QUERY_TABLE`, `DIALOG_QUERY_MAX_SIZE`, `DIALOG_QUERY_LANGUAGE`, `DIALOG_QUERY_LANGUAGE_CUSTOM`, `DESCRIPTION`, `SELECT_MODE`, `REFLECT_INPUT_CLASS_NAME`, `REFLECT_CLASS_NAME`, `REFLECT_INPUT_METHOD_NAME`, `REFLECT_METHOD_NAME`, `REFLECT_INPUT_PROPERTY_NAME`, `REFLECT_PROPERTY_NAME`, `SELECT_INPUT_MODE`, `HTTP_URL`, `INPUT_HTTP_URL`, `COMPANY_VIEW_FLAG`, `CREATED_ID`, `CREATED_BY`, `CREATION_DATE`, `CREATED_BY_IP`, `CREATED_FULL_NAME`, `LAST_UPDATED_ID`, `LAST_UPDATED_BY`, `LAST_UPDATE_DATE`, `LAST_UPDATED_BY_IP`, `LAST_UPDATED_FULL_NAME`, `TENANT_ID`, `VERSION`) VALUES (455568317855744, 'sou_purfix_price_contract', NULL, 'SOU_READ', NULL, 'allMatch', 'scc_npm_sou_purfix_price_line', 15, NULL, NULL, 'PUR_FIX_PRICE_LINE_ID', 'SELECT t.*,h.CREATE_USER_ORG_OU_NAME,h.CREATE_USER_ORG_OU_ID,h.CREATE_USER_ORG_OU_CODE,h.DESIGN_PROJECT_CODE FROM scc_npm_sou_purfix_price_line t INNER JOIN  scc_npm_sou_purfix_price_head h \nON t.PUR_FIX_PRICE_HEAD_ID =h.PUR_FIX_PRICE_HEAD_ID WHERE t.FIX_PRICE_STATUS = \'APPROVED\'  \nand (t.SIGN_CONTRACT_FLAG is null or t.SIGN_CONTRACT_FLAG <> \'Y\')\nAND t.DESIGN_PROJECT_CODE LIKE :query\nAND h.CREATE_USER_ORG_OU_NAME LIKE :query\nAND t.ITEM_CODE LIKE :query\nAND t.VENDOR_NAME LIKE :query', NULL, NULL, NULL, NULL, NULL, 'SELECT t.*,h.CREATE_USER_ORG_OU_NAME,h.CREATE_USER_ORG_OU_ID,h.CREATE_USER_ORG_OU_CODE,h.DESIGN_PROJECT_CODE FROM scc_npm_sou_purfix_price_line t INNER JOIN  scc_npm_sou_purfix_price_head h \nON t.PUR_FIX_PRICE_HEAD_ID =h.PUR_FIX_PRICE_HEAD_ID WHERE t.FIX_PRICE_STATUS = \'APPROVED\'  and  (t.SIGN_CONTRACT_FLAG IS NULL  OR t.SIGN_CONTRACT_FLAG <> \'Y\')', NULL, '查询集采定价单数据', 'SQL', '', '', '', '', '', '', 'SQL', '', '', 'N', 8123195817787648, 'super', '2023-12-15 11:45:33', '10.254.103.203', '超级管理员', 8123195817787648, 'super', '2024-01-02 17:51:03', '10.254.103.203', '超级管理员', NULL, 0);
